def for_plugin(p, rows):
    """The shared install, requirement and troubleshooting rows, without the standalone app for plugins that have none."""
    if p.get("standalone", True):
        return rows
    swap = [(" and a standalone app.", "."), (", the VST3 and the standalone app.", " and the VST3."),
            (" VST3 host or the standalone app.", " VST3 host."), (" AU or VST3 host, or the standalone app.", " AU or VST3 host.")]
    out = []
    for a, b in rows:
        if "standalone app" in b and not any(x in b for x, _ in swap):
            continue   # a row only about the standalone app
        for x, y in swap:
            b = b.replace(x, y)
        out.append((a, b))
    return out


