# site order = a sensible signal chain in a DAW, IN -> OUT: sound sources and tone first, then the bass bus and the
# mix buses, the master last. The home page's chain and the plugin grid both follow it.
ORDER = ["pyre", "krush", "shrapnel", "dark", "recoil", "spectrakill", "peakslayer", "transplant", "masterfuse", "flatline"]
PLUGINS.sort(key=lambda p: ORDER.index(p["slug"]))
